      "ko": "날렵하고 스타일리쉬한 동체에 숨겨진 화물칸과 오리진 사 특허 AIR 연료 시스템 기술이 135c 모델을 음악가, 택배원, 그리고 파티를 열고 싶은 모든 이를 위한 선택이 되도록 만들었습니다. 135c와 함께라면 당신이 무엇을 하던, 빠르게 그리고 멋있게 할 수 있을 겁니다."
