      "ko": "별들을 탐사하는 것은 가장 고귀한 노력입니다. 그것은 오리진 점프웍스사가 400i를 고성능 항로선도기로 만드는 계기가 되었습니다. 동급 최강의 운용 범위, 뛰어난 방어 능력, 그리고 기본으로 장착되는 스캐닝 레이더를 통해 400i가 어떤 은하의 황량한 변방이라도 오리진의 명성에 걸맞는 안락함과 우아함으로 탐사할 준비가 되었습니다."
