      "en": "Keep your airspace clear of danger with the Anvil HM6 Ballista. Originally designed to defend outposts from Vanduul attacks, this mobile missile defense system packs a powerful loadout, allowing the Ballista to stand firm against any threat, whether it arrives by air or land. The Snowblind variant comes in a grey camouflage pattern to keep it concealed against rocky or lunar terrain.",
      "ko": "앤빌 HM6 발리스타로 제공권을 장악해 보십시오. 본래 반둘의 공격으로 부터 전초기지를 지키기 위해 개발된 이 이동형 미사일 방어 체계는 강력한 탑재 장비를 갖추고 있습니다. 발리스타는 그 어떠한 위협에도 굳건히 버티며 지상이든 공중이든 이겨낼 수 있습니다. 스노우블라인드 파생형은 돌 투성이나 위성 같은 지표면에서 눈에 띄지 않도록 회색 위장 패턴이 그려져 있습니다."
