      "en": "Spark fear in the corridors of the most formidable gunships and frigates with the Ares Ion. This laser-equipped variant delivers extremely powerful shots to quickly disable the shields of even the biggest enemy vessels.",
      "ko": "아레스 이온으로 강력한 건쉽이나 프리깃 함선의 승무원에게 공포를 주십시오. 레이저가 장착된 이 변종은 극도로 강력한 사격으로 아무리 큰 적함이라도 방어막을 빠르게 무력화 시킬 수 있습니다."
