    "descriptions": {
      "en": "The Aurora is the modern day descendant of the Roberts Space Industries X-7 spacecraft which tested the very first jump engines. Utilitarian to a T, the Aurora is the perfect beginner's ship: what it lacks in style it makes up for in ample room for upgrade modules.",
      "ko": "오로라는 최초로 점프 엔진을 테스트한 로버츠 스페이스 인더스트리의 X-7 우주선을 현대화 한 후계기 입니다. 실용적인 오로라는 초보자를 위한 함선으로 업그레이드 모듈을 위한 공간을 확보하기위해 디자인을 희생했습니다."
    }
