    "descriptions": {
      "en": "Sleek, mean, and royal. The Cutlass Blue adds missiles, a more aggressive engine, and Durasteel holding cells in the cargo bay to the standard model. The Cutlass Blue is the outworld militia standard ship of choice for patrols.",
      "ko": "사납지만, 매끄럽고 위풍당당합니다. 커틀러스 블루에는 미사일과 더욱 공격적인 엔진, 그리고 화물칸에 듀라스틸로 만들어진 감옥을 탑재하고 있습니다. 커틀러스 블루는 변방 민병대가 정찰 함선으로 채택했습니다."
    }
