      "en": "Refining their renowned military-class superiority fighter with the most up-to-date technology, Anvil Aerospace has crafted the F7C-M Super Hornet Mk II,  retaining the second seat and ball turret that made the original a truly terrifying mark to engage.",
      "ko": "명망높은 군용급 제공 전투기를 앤빌 에어로스페이스는 최신 기술로 개량하여 F7C-M 슈퍼 호넷 Mk II를 제작했습니다. 이 기체는 원 기체를 교전하기에 두려운 존재로 만들었던 두 번째 좌석과 볼 터렛을 유지하고 있습니다."
