      "en": "Taking the framework of the Guardian fighter and adding even more offensive options, the Mirai Guardian MX packs additional firepower and armor ideal for overwhelming opponents. While not as nimble as the base Guardian, this heavy fighter is still more agile than many other ships in its class.",
      "ko": "가디언 전투기의 프레임워크에 더 많은 공격 옵션을 추가하여, 미라이 가디언 MX는 상대를 압도하기에 이상적인 추가 화력과 방어구를 갖추고 있습니다. 가디언 기본형만큼 민첩하지는 않지만, 이 중전투기는 여전히 동급의 함선들보다 기동성이 뛰어납니다."
