      "ko": "제작까지 거의 400년이 걸린, 그만한 가치가 있는 함선을 만나보세요. 크루거 인터갤럭틱은 회사 최초로 자체 제조 함선인 울프를 자랑스레 선보입니다. 속도와 스타일, 칼같은 정밀한 디자인을 모두 겸비한 L-22 울프는 크루거의 자랑일뿐만 아니라 두 개의 맞춤형 S4 레이저 리피터를 포함한 강력한 무장 구성을 갖추어 외로운 늑대 또는 무리로서 사냥할 준비가 되어 있습니다."
