      "ko": "M80으로 방어력을 포기하지 않으면서도 우아함을 만끽하세요. 오리진의 유명한 세련되고 정교한 디자인을 자랑하는 함선의 선체는, 순간적으로 전개되어 맹렬히 쏟아부을 수 있는 공격적인 무기 시스템을 교묘하게 감추고 있습니다."
