      "ko": "RSI의 고급 퀀텀 차단 함선으로 맨티스는 웨이-텍의 맞춤형 퀀텀 차단 장치를 가지고 있으며 퀀텀중인 함선을 멈추고 함선이 탈출하는 것을 방지할 수 있습니다."
