    "descriptions": {
      "en": "Building upon a robust and sturdy industrial frame, Greycat has crafted the MDC Mobile Defense Center into an effective combat vehicle ready to protect your interests from remote mining sites to patrolling high-value processing centers thanks to its mounted PDS turret.",
      "ko": "튼튼하고 견고하고 산업용 프레임의 기반으로, 그레이캣은 MDC 이동식 방어 센터를 효과적인 전투 차량으로 만들었습니다. 장착된 PDS 터렛으로 인해 원격지 채광 현장부터 고가치 처리 센터를 순찰하여 재산을 보호할 준비가 되어 있습니다."
    }
