      "en": "Consolidated Outland teamed up with custom tuning company Accelerated Mass Design to create a limited edition racer that features a ramped up fuel intake for faster recycling of the ship’s already impressive boost system. To cap off the collaboration, AMD enlisted resident underground artist Sektor8 to design the dynamic paint job.",
      "ko": "아웃랜드 사는 커스텀 튜닝업체, 엑셀레이티드 메스 디자인과 협업하여 이미 끝내주는 함선의 부스터 시스템의 싸이클을 더 빠르게 하기위해서 연료 흡입량을 늘린 한정판 레이싱 기체를 만들었습니다. 협업을 끝내기위해 AMD 사는 언더그라운드 아티스트 섹터8을 고용하여 역동적인 도색 작업을 하고 있습니다."
