      "ko": "중형 다목적 화물선에 스타일리쉬하고 컴팩트한 프레임, 다양한 기능을 갖춘 컨솔리데이티드 아웃랜드 사의 노매드는 자급자족하거나, 탁 트인 하늘의 기운을 만끽하거나, 새로운 모험을 시작하기를 갈망하는 이들을 위한 완벽한 해결책 입니다."
