      "en": "Whether for added security, exploring a system or simply the joy of flying, the Kruger Intergalactic’s P-72 Archimedes snub craft was designed to deliver exceptional handling and nimble acceleration in a sleek and stylish package.",
      "ko": "보안강화를 위해서 이던, 행성계 탐험이든, 아니면 그저 간단히 비행의 즐거움을 위한 것 이던, 크루거 인터갤럭틱 사의 초소형 전투기 P-72 아르키메데스는 탑승자에게 뛰어난 핸들링과 잘빠진 동체를 통한 빠른 가속력을 전해주기 위해서 만들어졌습니다."
