    "descriptions": {
      "en": "When RSI set out to make the definitive modern statement in persuasive prevention, they looked into their own past, to the historic gunships designated Perseus. Capable of shredding sub-capital class goliaths, the mere presence of a Perseus gunship in a blockade or patrol squad is enough to make your most aggressive enemies think twice before engaging, just like its vintage namesake.",
      "ko": "로버츠 스페이스 인더스트리는 전투를 예방할 수 있는 방법을 말하면서 자사의 역사에서 역사적인 건쉽인 페르세우스를 복원하기로 하였습니다. 서브 캐피탈 함선을 분쇄할 수 있는 페르세우스가 후방 부대나 정찰 부대에 있는 것만으로 강력한 적들이라도 페르세우스의 명성 때문에 전투를 주저할 것입니다."
    }
