      "en": "The Argo RAFT features a hefty 192 SCU cargo hold, and is capable of carrying standardized 32 SCU cargo containers. Perfect for entry-level haulers and old pros alike, the RAFT is an ideal solution for reliable local freight transport.",
      "ko": "아르고 래프트는 표준 32 SCU 컨테이너를 수납하여 192 SCU까지 운반할 수 있습니다. 엔트리급의 운반업자와 노련한 전문가 모두에게 알맞는 래프트는 신뢰성 있는 지역 화물 운송을 위한 완벽한 솔루션입니다."
