      "en": "This advanced racer features an advanced composite spaceframe that puts pure speed ahead of everything else... it's the ship for pilots who want to leave the competition in the dust.",
      "ko": "이 고급 레이서는 진보된 복합 소재의 스페이스프레임이 특징이며, 다른 무엇보다도... 순수하게 속도를 추구합니다. 흙먼지를 뒤집어 쓰는 경쟁을 하고 싶지 않는 조종사를 위한 함선입니다."
