      "ko": "이지스 다이나믹스는 그들의 레이븐 파생형들에 대한 기준을 또 다시 올렸습니다. 전 세대 기체 세이버의 속도와 기동성은 유지하면서 더 낮은 피탐지성으로 빠르고 은밀한 침투기가 되도록 말입니다."
