      "ko": "RSI는 스콜피우스 특유의 가변형 이중날개 구성을 업데이트하고 사내 팀이 독점적으로 설계한 맞춤형 퀀텀 댐프너와 EMP 장치를 추가하여 강력한 스콜피우스 안타레스를 탄생시켰습니다. 저지력을 염두에 두고 제작된 스콜피우스 안타레스는 어떤 추격전이라도 빠르게 마무리할 수 있도록 설계되었습니다."
