      "en": "Even in the most remote of planetside destinations, there are people who could use a helping hand. Designed by RSI to cross even the most rugged terrain, the Ursa Medivac features a Tier 3 Medical Bed ideal for offering aid wherever it's needed most.",
      "ko": "행성의 가장 외진 곳에도 도움의 손길을 필요로 하는 사람들이 있습니다. 가장 험준한 지형도 통과할 수 있도록 설계한 RSI 우르사 메디백은 티어 3 의료용 침대를 갖추고 있어 가장 필요한 곳에 도움을 제공하는 데 이상적입니다."
