      "en": "Answer to no one, cut out the middle man, and throw caution to the wind. Rip wrecks like a pro and carve out your own place in the great big empty behind the stick of this rough, rugged salvage machine from Drake Interplanetary.",
      "ko": "드레이크 인터플래네터리에서 나온 터프하고 야무진 인양 머신을 타면 아무에게도 이야기할 필요가 없습니다. 직접, 마음 가는대로 프로처럼 잔해를 뜯어낼 수 있습니다. 자신의 자리를 직접 개척하십시오."
