      "en": "Built to endure tougher environments and look good doing it, the X1 Force is a modified version of the base X1 model featuring additional defensive elements to toughen up this speedy and agile open-canopy bike, allowing it to serve in a variety of roles, from exploring worlds to potential security infiltration ops.",
      "ko": "거친 환경을 견뎌낼 수 있도록 만들어진 X1 포스는 X1의 개량된 버전으로, 추가적인 보강물을 통해 오픈 캐노피 바이크를 강화함으로서 탐험에서 잠입 임무까지 다양한 역할을 수행할 수 있도록 만들었습니다."
